// Autogenerated Clip Studio Paint extracted textures and materials for Oniri
// Includes genuine CSP tip materials, paper grain textures, and effect star stamps

export const TIP_FLAT_SQUARE_DATA = 'data:image/png;base64,';
export const TIP_GASAGASA_DATA = 'data:image/png;base64,';
export const TIP_BRUSH02_DATA = 'data:image/png;base64,';
export const TIP_STAR02_DATA = 'data:image/png;base64,';
export const TIP_STAR04_DATA = 'data:image/png;base64,';
export const PAPER_OIL_DATA = 'data:image/png;base64,';
export const PAPER_PENCIL_DATA = 'data:image/png;base64,';

export interface TextureAsset {
  image: HTMLImageElement;
  loaded: boolean;
  dataCanvas?: HTMLCanvasElement;
  pixelData?: Uint8ClampedArray;
  toothData?: Float32Array; // Normalized high-contrast paper tooth [0..1]
  pattern?: CanvasPattern;
  width: number;
  height: number;
}

const assets = new Map<string, TextureAsset>();
const listeners = new Set<() => void>();

export function subscribeTextureAssets(fn: () => void): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

function notifyListeners(): void {
  for (const fn of listeners) {
    try { fn(); } catch { /* ignore */ }
  }
}

function createAsset(src: string): TextureAsset {
  const img = new Image();
  const asset: TextureAsset = {
    image: img,
    loaded: false,
    width: 0,
    height: 0,
  };

  const onReady = () => {
    if (asset.loaded) return;
    asset.loaded = true;
    asset.width = img.naturalWidth || img.width || 300;
    asset.height = img.naturalHeight || img.height || 300;
    
    try {
      const cvs = document.createElement('canvas');
      cvs.width = asset.width;
      cvs.height = asset.height;
      const ctx = cvs.getContext('2d', { willReadFrequently: true });
      if (ctx) {
        ctx.drawImage(img, 0, 0);
        asset.dataCanvas = cvs;
        const imgData = ctx.getImageData(0, 0, asset.width, asset.height);
        asset.pixelData = imgData.data;

        // Precompute high-contrast paper tooth matrix [0..1] where 0 = deep valley, 1 = tooth peak
        const total = asset.width * asset.height;
        const tooth = new Float32Array(total);
        const data = asset.pixelData;
        for (let i = 0; i < total; i++) {
          const idx = i * 4;
          const r = data[idx];
          const g = data[idx + 1];
          const b = data[idx + 2];
          const a = data[idx + 3] / 255;
          // In grayscale paper textures, luminance indicates paper tooth
          // In alpha masks, alpha indicates paper tooth
          let val = 1.0;
          if (a < 0.95) {
            // Alpha mask (e.g. pencil paper)
            val = a;
          } else {
            // RGB luminance (e.g. oil canvas)
            const lum = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
            // Contrast boost for dramatic, crisp paper grain
            val = Math.max(0, Math.min(1, (lum - 0.20) / 0.60));
          }
          tooth[i] = val;
        }
        asset.toothData = tooth;
      }
    } catch {
      // ignore
    }

    notifyListeners();
  };

  img.onload = onReady;
  img.src = src;
  if (img.complete && img.naturalWidth > 0) {
    onReady();
  }
  return asset;
}

export function initBrushTextures(): void {
  if (assets.size > 0) return;
  assets.set('flat-square', createAsset(TIP_FLAT_SQUARE_DATA));
  assets.set('gasagasa', createAsset(TIP_GASAGASA_DATA));
  assets.set('brush02', createAsset(TIP_BRUSH02_DATA));
  assets.set('star02', createAsset(TIP_STAR02_DATA));
  assets.set('star04', createAsset(TIP_STAR04_DATA));
  assets.set('oil-paint', createAsset(PAPER_OIL_DATA));
  assets.set('pencil-paper', createAsset(PAPER_PENCIL_DATA));
}

export function getBrushTextureAsset(id: string): TextureAsset | undefined {
  if (assets.size === 0) {
    initBrushTextures();
  }
  return assets.get(id);
}

/**
 * Samples the paper tooth at coordinate (x, y) with scaling.
 * Returns 0.0 (deep paper valley / uninked pore) to 1.0 (paper peak / full tooth).
 */
export function samplePaperGrain(textureId: string, x: number, y: number, scale = 1.0): number {
  const asset = getBrushTextureAsset(textureId);
  if (!asset || !asset.loaded || !asset.toothData || asset.width === 0) {
    return 1.0;
  }
  const s = Math.max(0.05, scale);
  const tx = Math.floor(Math.abs(x * s)) % asset.width;
  const ty = Math.floor(Math.abs(y * s)) % asset.height;
  return asset.toothData[ty * asset.width + tx];
}
